    let encoded = RequestMessage.encode(protoInit.requestData || {}).finish();
    let length = encoded.length;
    let body = new Uint8Array(5 + length);
    body.set([0, (length >>> 24) & 255, (length >>> 16) & 255, (length >>> 8) & 255, length & 255], 0);
    body.set(encoded, 5);
