function __lnr_isUrlAbsolute(url) {
    if (!url) {
        return false;
    }
    if (url.indexOf("//") === 0) {
        return true;
    }
    if (url.indexOf("://") === -1 || url.indexOf(".") === -1 || url.indexOf("/") === -1) {
        return false;
    }
    if (url.indexOf(":") > url.indexOf("/")) {
        return false;
    }
    return url.indexOf("://") < url.indexOf(".");
}

